import os, glob, json
import openpyxl, docx, pypdf

def dump_pdf(path):
    print('=== PDF:', path)
    reader = pypdf.PdfReader(path)
    for i, page in enumerate(reader.pages):
        print(f'--- Page {i+1} ---')
        print(page.extract_text())

