    print('=== DOCX:', path)
    doc = docx.Document(path)
    for p in doc.paragraphs:
        if p.text.strip(): print(p.text)
    for t in doc.tables:
        for row in t.rows:
            print([c.text.strip() for c in row.cells])

def dump_xlsx(path):
    print('=== XLSX:', path)
